-- Vector common type of conditionals, GREATEST/LEAST, comparisons and UNION (issue #31919).
-- Contract: docs/sql/vector-common-type.md.
drop database if exists vec_common_type;
create database vec_common_type;
use vec_common_type;
create table x (id int primary key, f32 vecf32(4), f64 vecf64(4), bf16 vecbf16(4), f16 vecf16(4), i8 vecint8(4), u8 vecuint8(4), f8 vecf8(4), f4 vecf4(4));
create table y (id int primary key, f32 vecf32(4), f64 vecf64(4), bf16 vecbf16(4), f16 vecf16(4), i8 vecint8(4), u8 vecuint8(4), f8 vecf8(4), f4 vecf4(4));
insert into x values (1, '[1,3,0,6]', '[1,3,0,6]', '[1,3,0,6]', '[1,3,0,6]', '[1,3,0,6]', '[1,3,0,6]', '[1,3,0,6]', '[1,3,0,6]'), (2, null, null, null, null, null, null, null, null);
insert into y values (1, '[6,2,1,0]', '[6,2,1,0]', '[6,2,1,0]', '[6,2,1,0]', '[6,2,1,0]', '[6,2,1,0]', '[6,2,1,0]', '[6,2,1,0]'), (2, '[6,2,1,0]', '[6,2,1,0]', '[6,2,1,0]', '[6,2,1,0]', '[6,2,1,0]', '[6,2,1,0]', '[6,2,1,0]', '[6,2,1,0]');

-- Values: every operator over every pair of vector types; x.id = 2 holds NULLs.
-- Result types: desc. Mixed types resolve to vecf64 when either side is vecf64, else vecf32.
create table r_f32 as select x.id, case when x.id = 1 then x.f32 else y.f32 end case_f32, ifnull(x.f32, y.f32) ifnull_f32, if(x.id = 1, x.f32, y.f32) if_f32, coalesce(x.f32, y.f32) coalesce_f32, nullif(x.f32, y.f32) nullif_f32, greatest(x.f32, y.f32) greatest_f32, least(x.f32, y.f32) least_f32, x.f32 = y.f32 eq_f32, x.f32 <> y.f32 ne_f32, x.f32 < y.f32 lt_f32, x.f32 between y.f32 and y.f32 between_f32, x.f32 <=> y.f32 nullsafe_f32, x.f32 in (y.f32) in_f32, case when x.id = 1 then x.f32 else y.f64 end case_f64, ifnull(x.f32, y.f64) ifnull_f64, if(x.id = 1, x.f32, y.f64) if_f64, coalesce(x.f32, y.f64) coalesce_f64, nullif(x.f32, y.f64) nullif_f64, greatest(x.f32, y.f64) greatest_f64, least(x.f32, y.f64) least_f64, x.f32 = y.f64 eq_f64, x.f32 <> y.f64 ne_f64, x.f32 < y.f64 lt_f64, x.f32 between y.f64 and y.f64 between_f64, x.f32 <=> y.f64 nullsafe_f64, x.f32 in (y.f64) in_f64, case when x.id = 1 then x.f32 else y.bf16 end case_bf16, ifnull(x.f32, y.bf16) ifnull_bf16, if(x.id = 1, x.f32, y.bf16) if_bf16, coalesce(x.f32, y.bf16) coalesce_bf16, nullif(x.f32, y.bf16) nullif_bf16, greatest(x.f32, y.bf16) greatest_bf16, least(x.f32, y.bf16) least_bf16, x.f32 = y.bf16 eq_bf16, x.f32 <> y.bf16 ne_bf16, x.f32 < y.bf16 lt_bf16, x.f32 between y.bf16 and y.bf16 between_bf16, x.f32 <=> y.bf16 nullsafe_bf16, x.f32 in (y.bf16) in_bf16, case when x.id = 1 then x.f32 else y.f16 end case_f16, ifnull(x.f32, y.f16) ifnull_f16, if(x.id = 1, x.f32, y.f16) if_f16, coalesce(x.f32, y.f16) coalesce_f16, nullif(x.f32, y.f16) nullif_f16, greatest(x.f32, y.f16) greatest_f16, least(x.f32, y.f16) least_f16, x.f32 = y.f16 eq_f16, x.f32 <> y.f16 ne_f16, x.f32 < y.f16 lt_f16, x.f32 between y.f16 and y.f16 between_f16, x.f32 <=> y.f16 nullsafe_f16, x.f32 in (y.f16) in_f16, case when x.id = 1 then x.f32 else y.i8 end case_i8, ifnull(x.f32, y.i8) ifnull_i8, if(x.id = 1, x.f32, y.i8) if_i8, coalesce(x.f32, y.i8) coalesce_i8, nullif(x.f32, y.i8) nullif_i8, greatest(x.f32, y.i8) greatest_i8, least(x.f32, y.i