desc r_f32;
select * from r_f32 order by id;
create table u_f32 as select 1 o, f32 v_f32, f32 v_f64, f32 v_bf16, f32 v_f16, f32 v_i8, f32 v_u8, f32 v_f8, f32 v_f4, f32 v_str from x where id = 1 union all select 2, f32, f64, bf16, f16, i8, u8, f8, f4, '[0,0,0,0]' from y where id = 1;
desc u_f32;
select * from u_f32 order by o;
