create table u_f4 as select 1 o, f4 v_f32, f4 v_f64, f4 v_bf16, f4 v_f16, f4 v_i8, f4 v_u8, f4 v_f8, f4 v_f4, f4 v_str from x where id = 1 union all select 2, f32, f64, bf16, f16, i8, u8, f8, f4, '[0,0,0,0]' from y where id = 1;
desc u_f4;
select * from u_f4 order by o;

-- Multi-branch CASE over three vector types.
select x.id, case when x.id = 1 then x.bf16 when x.id = 2 then y.f16 else y.i8 end v from x join y on x.id = y.id order by x.id;
select x.id, case when x.id = 1 then x.u8 when x.id = 2 then y.f64 else '[9,9,9,9]' end v from x join y on x.id = y.id order by x.id;

-- Prepared statements.
prepare s1 from 'select coalesce(?, bf16) v from x order by id';
set @v = '[2,2,2,2]';
execute s1 using @v;
prepare s2 from 'select v from (select 1 o, bf16 v from x where id = 1 union all select 2, i8 from y where id = 1) t order by o';
execute s2;
deallocate prepare s1;
deallocate prepare s2;

-- Explicit casts from vecf8/vecf4 to vecf64.
select cast(f8 as vecf64(4)) f8_to_f64, cast(f4 as vecf64(4)) f4_to_f64 from x order by id;
select cast(f8 as vecf64(3)) from x where id = 1;
select cast(f8 as vecbf16(4)) from x where id = 1;

-- Rejections: dimension mismatch and a non-string scalar.
select case when id = 1 then f32 else cast('[1,2,3]' as vecf64(3)) end from x;
select coalesce(bf16, cast('[1,2,3]' as vecint8(3))) from x;
select greatest(f16, cast('[1,2,3]' as vecf8(3))) from x;
select f8 = cast('[1,2,3]' as vecf32(3)) from x;
select f32 = cast('[1,2,3]' as vecf64(3)) from x;
select f4 from x union all select cast('[1,2,3]' as vecf16(3));
select case when id = 1 then f32 else 7 end from x;
select greatest(i8, 7) from x;
select ifnull(u8, 7) from x;

select coalesce(f32, json_object('a', 1)) from x;
select greatest(f32, cast('abc' as varbinary(12))) from x;
select case when id = 1 then f8 else cast('abc' as binary(12)) end from x;

-- BETWEEN with constant bounds and with prepared parameters.
select id, f32 between cast('[0,0,0,0]' as vecf32(4)) and cast('[9,9,9,9]' as vecf32(4)) r from x order by id;
select id, bf16 between '[0,0,0,0]' and '[9,9,9,9]' r from x order by id;
select id, i8 between cast('[0,0,0,0]' as vecf64(4)) and cast('[1,3,0,6]' as vecf8(4)) r from x order by id;
select id, f4 between cast('[1,3,0,7]' as vecf16(4)) and cast('[9,9,9,9]' as vecuint8(4)) r from x order by id;
prepare s3 from 'select id, f16 between ? and ? r from x order by id';
set @lo = '[0,0,0,0]';
set @hi = '[1,3,0,6]';
execute s3 using @lo, @hi;
deallocate prepare s3;

-- Same type, different dimension: comparison evaluates, the other operators reject.
select cast('[1,2,3]' as vecbf16(3)) = cast('[1,2,3,4]' as vecbf16(4)) r;
select case when true then cast('[1,2,3]' as vecbf16(3)) else cast('[1,2,3,4]' as vecbf16(4)) end r;
select if(true, cast('[1,2,3]' as vecbf16(3)), cast('[1,2,3,4]' as vecbf16(4))) r;
select ifnull(cast('[1,2,3]' as vecbf16(3)), cast('[1,2,3,4]' as vecbf16(4))) r;
select coalesce(cast('[1,2,3]' as vecbf16(3)), cast('[1,2,3,4]' as vecbf16(4))) r;
select greatest(cast('[1,2,3]' as vecbf16(3)), cast('[1,2,3,4]' as vecbf16(4))) r;
select least(cast('[1,2,3]' as vecbf16(3)), cast('[1,2,3,4]' as vecbf16(4))) r;
select cast('[1,2,3]' as vecbf16(3)) union all select cast('[1,2,3,4]' as vecbf16(4));

-- UNION without ALL.
create table u_distinct as select f8 v from x where id = 1 union select f64 from y where id = 1 union select i8 from x where id = 1;
desc u_distinct;
select count(*) from u_distinct;

-- The same rule with sql_mode MATRIXONE_NATIVE.
set @saved_sql_mode = @@sql_mode;
set session sql_mode = 'MATRIXONE_NATIVE';
create table native_r as select x.id, case when x.id = 1 then x.bf16 else y.f64 end c, if(x.id = 1, x.f8, y.i8) i, ifnull(x.u8, '[0,0,0,0]') n, coalesce(x.f8, y.f64) co from x join y on x.id = y.id;
desc native_r;
select * from native_r order by id;
select case when id = 1 then f32 else cast('[1,2,3]' as vecf64(3)) end from x;
set session sql_mode = @saved_sql_mode;

-- Examples of docs/sql/vector-common-type.md.
create table t (id int, a vecbf16(3), b vecint8(3), c vecf64(3));
insert into t values (1, '[1,2,3]', null, '[4,5,6]');
create table doc_r as select coalesce(b, a) ba, coalesce(b, a, c) bac, a = c eq, ifnull(b, '[0,0,0]') b_str, case when id = 1 then a else '[9,9,9]' end a_str from t;
desc doc_r;
select * from doc_r;
create table doc_u as select a v from t union all select b from t;
desc doc_u;
select count(*) from doc_u;

drop database vec_common_type;
